import subprocess

def run(input):
    def git(*a):
        return subprocess.run(["git", "-C", input["wt"]] + list(a),
                              capture_output=True, text=True)
    git("fetch", "origin")
    r = git("rebase", "origin/main")
    if r.returncode != 0:
        git("rebase", "--abort")
        return {"ok": False,
                "why": ((r.stderr or "") + (r.stdout or ""))[-400:]}
    git("push", "origin", "--delete", input["branch"])
    return {"ok": True}
